'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const date=n=>(n.approx?'c. ':'')+(n.year<0?Math.abs(n.year)+' BCE':n.year+' CE');
const dMap=new Map(discoveries.map(n=>[n.id,n])),pMap=new Map(people.map(n=>[n.id,n]));
const palette={Electricity:'#376454',Atoms:'#547e88',Quantum:'#846946',Radioactivity:'#a16b55',Genetics:'#806581',Mathematics:'#705b76',Astronomy:'#536f8b',Mechanics:'#88694a',Computing:'#367679',Medicine:'#975a51',Biology:'#5e7950',Chemistry:'#927235','Earth science':'#7c6950',Climate:'#467b75',Engineering:'#777257'};
let widerNetwork=false,networkView='focus';
let mode='people',selected='raman',zoom=.85,journey=null,step=0,limit=24,storyCategory='All stories',lastReaderTrigger=null,storyLimit=6;
const symmetric=e=>['Collaboration','Rivalry','Debate','Context','Shared milestone','Connected ideas','Correspondence'].includes(e[2]);
function nodes(){return mode==='people'?people:discoveries}
function edges(){return mode==='people'?peopleEdges:discoveryEdges}
function nodeMap(){return mode==='people'?pMap:dMap}
function sourceLink(key){const s=sources[key];return s?`<a class="source" href="${esc(s[1])}" target="_blank" rel="noopener">${esc(s[0])}</a>`:''}
function relationMatch(e){const r=$('#relation').value;if(r==='all')return true;if(r==='personal')return !['Shared milestone','Connected ideas','Context','Background'].includes(e[2]);if(r==='Rivalry')return ['Rivalry','Debate'].includes(e[2]);if(r==='Evidence')return ['Evidence','Tested'].includes(e[2]);if(r==='ideas')return !['Mentorship','Collaboration','Rivalry','Debate','Evidence','Tested'].includes(e[2]);return e[2]===r}
function eraMatch(n){const ranges={ancient:[-Infinity,499],medieval:[500,1499],early:[1500,1799],nineteenth:[1800,1899],modern:[1900,1949],late:[1950,1999],current:[2000,Infinity]},r=ranges[$('#era').value];return !r||(n.year>=r[0]&&n.year<=r[1])}
function filtered(){const q=norm($('#search').value.trim()),f=$('#field').value;const connected=new Set(edges().filter(relationMatch).flatMap(e=>e.slice(0,2)));return nodes().filter(n=>(f==='All'||n.field===f||n.fields?.includes(f))&&eraMatch(n)&&($('#relation').value==='all'||connected.has(n.id))&&(!q||norm([n.title,n.text,n.field,n.location,...(n.people||[]).map(id=>pMap.get(id)?.title),...(n.contributions||[]).map(id=>dMap.get(id)?.title)].join(' ')).includes(q))).sort((a,b)=>a.year-b.year||a.title.localeCompare(b.title))}
function clearFilters(){for(const [id,v] of [['search',''],['field','All'],['era','all'],['relation','all']])$('#'+id).value=v;limit=24}
function selectNode(id,newMode=mode,keepJourney=false){mode=newMode;selected=id;if(!keepJourney)journey=null;render();history.replaceState(null,'',`#node=${mode==='people'?'p':'d'}/${encodeURIComponent(id)}`)}
function openNode(id,newMode){closeReader(false);clearFilters();selectNode(id,newMode);$('#explore').scrollIntoView({behavior:'smooth'});$('#detail').scrollTop=0}
function mediaImage(key,cls='',lazy=true){const a=visualAssets[key];return a?`<img class="${esc(cls)}" src="${esc(a.src)}" alt="${esc(a.alt)}" width="${a.width}" height="${a.height}" loading="${lazy?'lazy':'eager'}" decoding="async">`:''}
function imageCredit(key){const a=visualAssets[key];return `<details class="image-credit"><summary>Image credit & source</summary><span>${esc(a.credit)} <a href="${esc(a.source)}" target="_blank" rel="noopener">Image source</a> · <a href="${esc(a.licenseUrl)}" target="_blank" rel="noopener">${esc(a.license)}</a></span></details>`}
function mediaFigure(key,cls=''){const a=visualAssets[key];return a?`<figure class="archive-figure ${esc(cls)}"><a class="image-original" href="${esc(a.src)}" target="_blank" rel="noopener" aria-label="Open full image: ${esc(a.alt)}">${mediaImage(key)}</a><figcaption>${esc(a.caption)}${imageCredit(key)}</figcaption></figure>`:''}
function storyCover(s){const v=storyVisuals[s.id];return v?`<div class="story-cover ${v.hero?'story-cover-scene':''}">${v.hero?`<div>${mediaImage(v.hero)}</div>`:''}${(v.portraits||[]).map(p=>`<div>${mediaImage(p.key,'',true)}<span>${esc(p.name)}</span></div>`).join('')}<small>AN ILLUSTRATED HISTORY</small></div>`:''}
function storyPortraits(s){const v=storyVisuals[s.id];return v?`${v.hero?mediaFigure(v.hero,'story-lead-image'):''}<div class="story-portrait-pair ${(v.portraits||[]).length===1?'single-portrait':''}" ${v.portraits?'':'hidden'}>${(v.portraits||[]).map(p=>`<figure><div class="portrait-mat">${mediaImage(p.key,'',false)}</div><figcaption><small>${esc(p.role)}</small><strong>${esc(p.name)}</strong><p>${esc(visualAssets[p.key].caption)}</p>${imageCredit(p.key)}</figcaption></figure>`).join('')}</div>`:''}
function nodeVisual(n){return mode==='people'?personVisuals[n.id]:discoveryVisuals[n.id]}
function card(n){return `<button class="catalogue-card ${n.id===selected?'active':''}" data-node="${esc(n.id)}">${nodeVisual(n)?mediaImage(nodeVisual(n),mode==='people'?'catalogue-portrait':'catalogue-event'): ''}<span class="card-meta">${esc(date(n))} · ${esc(n.field)}</span><strong>${esc(n.title)}</strong><small>${esc(n.location||'')}${mode==='people'?' · contribution date':''}</small></button>`}
function render(){const list=filtered();if(!list.some(n=>n.id===selected)){selected=list[0]?.id||null;journey=null}const ids=new Set(list.map(n=>n.id)),links=edges().filter(e=>ids.has(e[0])&&ids.has(e[1])&&relationMatch(e));
$$('[data-mode]').forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
$('#count').textContent=`${list.length} ${mode==='people'?'scientists':'milestones'} · ${links.length} mapped connections in these results`;
$('#map-caption').textContent=mode==='timeline'?'CHRONOLOGY OF SELECTED MILESTONES':networkView==='all'?'THE COMPLETE NETWORK':'CONNECTIONS AROUND YOUR SELECTION';
$('#browse-title').textContent=mode==='people'?'Browse scientists':'Browse discoveries';$('#browse-note').textContent=mode==='people'?'Dates show the first contribution mapped here, not birth.':'Select a card to centre its connections.';
$('#fit-map').disabled=mode==='timeline';$('#network-depth').disabled=mode==='timeline';$('#network-depth').textContent=networkView==='all'?'Focus on selection':widerNetwork?'Whole atlas':'Expand this thread';$('#network-depth').setAttribute('aria-pressed',widerNetwork);$('#zoom-in').disabled=mode==='timeline';$('#zoom-out').disabled=mode==='timeline';
$('#catalogue').innerHTML=mode==='timeline'?'':list.slice(0,limit).map(card).join('');$('.browse-head').hidden=mode==='timeline';$('#load-more').hidden=mode==='timeline'||limit>=list.length;$('#load-more').textContent=`Show more (${Math.max(0,list.length-limit)} remaining)`;
if(!list.length){$('#map').innerHTML='<div class="empty"><h3>No matches in this view.</h3><p>Try a broader search, another era or All relationships.</p><button data-clear>Clear filters</button></div>'}
else if(mode==='timeline'){$('#map').innerHTML='<div class="timeline">'+list.map(n=>`<button data-node="${esc(n.id)}" class="${n.id===selected?'active':''}"><span>${esc(date(n))}</span><div><strong>${esc(n.title)}</strong><small>${esc(n.field)} · ${esc(n.people.map(id=>pMap.get(id).title).join(', ')||'Collective achievement')}</small></div></button>`).join('')+'</div>'}
else if(networkView==='all')renderOverview(list,links);else renderNetwork(list,links);
renderDetail();bindNodeButtons($('#explore'));
const clear=$('[data-clear]');if(clear)clear.onclick=()=>{clearFilters();render()};
}
function wrap(text,max=29){let lines=[''];for(const word of text.split(' ')){let i=lines.length-1;if(lines[i]&&(lines[i]+' '+word).length>max)lines.push(word);else lines[i]+=(lines[i]?' ':'')+word}return lines}
let constellation;
const nightPalette={Electricity:'#7fbda0',Atoms:'#8bcee0',Quantum:'#d6b579',Radioactivity:'#e5a887',Genetics:'#d2a5dd',Mathematics:'#b8ade7',Astronomy:'#9bbbe5',Mechanics:'#d7b790',Computing:'#85d8d2',Medicine:'#eba6a1',Biology:'#a6cb85',Chemistry:'#d9cb86','Earth science':'#c2b08b',Climate:'#8bccc1',Engineering:'#bfbc9c'};
function renderConstellation(list,links,focus){
 if(!constellation)constellation=new ScienceConstellation($('#map'));
 constellation.mount({list,links,selected,focus,wider:widerNetwork,mode,escape:esc,date,symmetric,colors:nightPalette,visual:n=>nodeVisual(n),asset:key=>visualAssets[key]?.src,onSelect:id=>{selectNode(id);$('#detail').scrollTop=0},onFocus:id=>{selected=id;networkView=networkView==='all'?'focus':'all';widerNetwork=false;render()}});
 $('#count').textContent=`${constellation.ns.length} ${mode==='people'?'scientists':'milestones'} · ${constellation.ls.length} connections ${focus?'in this thread':'in the atlas'}`;
}
function renderOverview(list,links){renderConstellation(list,links,false)}
function renderNetwork(list,links){renderConstellation(list,links,true)}
function bindNodeButtons(root){root.querySelectorAll('[data-node]').forEach(b=>{b.onclick=()=>{selectNode(b.dataset.node);$('#detail').scrollTop=0;if(innerWidth<760)$('#detail').scrollIntoView({behavior:'smooth',block:'start'})};if(b.tagName.toLowerCase()==='g')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.onclick()}}})}
function renderDetail(){const n=nodeMap().get(selected);if(!n){$('#detail').innerHTML='<h3>No selection</h3><p>Broaden the filters to explore more of the collection.</p>';return}const linked=edges().filter(e=>(e[0]===n.id||e[1]===n.id)&&relationMatch(e)),relatedStories=narratives.filter(s=>(mode==='people'?s.people:s.discoveries).includes(n.id));
$('#detail').innerHTML=`<p class="eyebrow">${journey?`GUIDED ROUTE · ${step+1} / ${journey.ids.length}`:esc(n.field)}</p><h3>${esc(n.title)}</h3><div class="detail-year">${mode==='people'?'EARLIEST MAPPED CONTRIBUTION':'MILESTONE'} · ${esc(date(n))}</div><p class="place">${esc(n.location)}</p>${nodeVisual(n)?mediaFigure(nodeVisual(n),mode==='people'?'detail-portrait':'detail-event'): ''}<p>${esc(n.text)}</p><details class="detail-sources"><summary>Read the source</summary>${sourceLink(n.source)}</details>${journey?`<div class="story-nav"><button id="prev" ${step===0?'disabled':''}>Previous</button><button id="next" ${step===journey.ids.length-1?'disabled':''}>Next stop</button></div><button id="end" class="person-link">Exit guided route</button>`:''}${relatedStories.length?`<div class="detail-rule"><h4>THERE IS A STORY HERE</h4>${relatedStories.map(s=>`<button class="related story-link" data-narrative="${s.id}">${esc(s.title)}<small>${esc(s.category)} · Read the story</small></button>`).join('')}</div>`:''}
<div class="detail-rule"><h4>${mode==='people'?'MILESTONES IN THIS ATLAS':'PEOPLE ASSOCIATED WITH THIS MILESTONE'}</h4>${mode==='people'?(n.contributions.map(id=>`<button class="person-link" data-discovery="${esc(id)}">${esc(dMap.get(id).title)}</button>`).join('')||'<p>Mapped here through teaching or relationships.</p>'):(n.people.map(id=>`<button class="person-link" data-person="${esc(id)}">${esc(pMap.get(id).title)}</button>`).join('')||'<p>A collective achievement, without a single named discoverer.</p>')}</div>
<div class="detail-rule"><h4>FOLLOW THE CONNECTIONS</h4>${linked.map(e=>{const id=e[0]===n.id?e[1]:e[0],other=nodeMap().get(id);return `<div class="connection"><button class="related" data-related="${esc(id)}">${esc(other.title)}<small>${esc(e[2])} · ${symmetric(e)?'mutual or contextual link':e[1]===n.id?'into this selection':'from this selection'}</small></button><details class="connection-explanation"><summary>Why they connect</summary><p>${esc(e[3])}</p>${sourceLink(e[4])}</details></div>`}).join('')||'<p>No relationship of this type has been mapped here yet. This does not imply that none existed.</p>'}</div>`;
$('#detail').querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{clearFilters();selectNode(b.dataset.person,'people');$('#detail').scrollTop=0});$('#detail').querySelectorAll('[data-discovery]').forEach(b=>b.onclick=()=>{clearFilters();selectNode(b.dataset.discovery,'discoveries');$('#detail').scrollTop=0});$('#detail').querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{clearFilters();selectNode(b.dataset.related);$('#detail').scrollTop=0});bindStoryButtons($('#detail'));
if(journey){$('#prev').onclick=()=>{step--;selected=journey.ids[step];render();$('#detail').scrollTop=0};$('#next').onclick=()=>{step++;selected=journey.ids[step];render();$('#detail').scrollTop=0};$('#end').onclick=()=>{journey=null;render()}}
}
function renderStories(){const q=norm($('#story-search').value),shown=narratives.filter(s=>(storyCategory==='All stories'||s.category===storyCategory)&&(!q||norm([s.title,s.dek,s.category,...s.people.map(id=>pMap.get(id).title),...s.chapters.flat(),...(s.more||[]).flat()].join(' ')).includes(q)));
$('#story-count').textContent=`${shown.length} stories to explore`;$('#more-stories').hidden=shown.length<=storyLimit;$('#more-stories').textContent=`More stories (${Math.max(0,shown.length-storyLimit)})`;
$('#narrative-cards').innerHTML=shown.length?shown.slice(0,storyLimit).map((s,i)=>`<button class="narrative-card" data-narrative="${s.id}">${storyCover(s)}<div class="story-card-top"><span>${esc(s.category)}</span><span>${esc(s.period)}</span></div><p class="story-kicker">${esc(s.kicker)}</p><h3>${esc(s.title)}</h3><p class="story-preview">${esc(s.dek.length>120?s.dek.slice(0,117).replace(/\s+\S*$/,'')+'…':s.dek)}</p><span class="story-card-bottom">Read the story <span>${readingMinutes(s)} min read</span></span></button>`).join(''):'<p class="empty">No stories match. Try another theme or clear your search.</p>';
$$('[data-story-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.storyCategory===storyCategory));bindStoryButtons($('#narrative-cards'));
}
function readingMinutes(s){return Math.max(1,Math.ceil(s.chapters.map(c=>c.join(' ')).join(' ').split(/\s+/).length/180))}
function bindStoryButtons(root){root.querySelectorAll('[data-narrative]').forEach(b=>b.onclick=()=>{lastReaderTrigger=b;openStory(b.dataset.narrative)})}
function storyDeepDive(s){
 const milestones=s.discoveries.map(id=>dMap.get(id)).sort((a,b)=>a.year-b.year);
 const ids=new Set(s.discoveries);
 const links=discoveryEdges.filter(e=>ids.has(e[0])||ids.has(e[1]));
 const unique=[...new Map(links.map(e=>[e[0]+':'+e[1]+':'+e[2],e])).values()].slice(0,8);
 return `<details class="story-deep-dive"><summary><span>Read more</span><small>The people, the evidence and what happened next</small></summary><div class="deep-content"><p class="eyebrow">BEYOND THE SHORT STORY</p>${(s.more||[]).map(([heading,body,source])=>`<section class="deep-milestone"><h2>${esc(heading)}</h2><p>${esc(body)}</p>${sourceLink(source)}</section>`).join('')}<h2>The discoveries in context</h2>${milestones.map(n=>`<section class="deep-milestone"><p class="eyebrow">${esc(date(n))} · ${esc(n.location)}</p><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${sourceLink(n.source)}</section>`).join('')}<h2>The people behind the work</h2>${s.people.map(id=>{const p=pMap.get(id);return `<section><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p>${sourceLink(p.source)}</section>`}).join('')}${unique.length?`<h2>How this story connects</h2><p>These links distinguish evidence and influence from broader historical context.</p>${unique.map(e=>`<section><p class="eyebrow">${esc(e[2])}</p><h3>${esc(dMap.get(e[0]).title)} → ${esc(dMap.get(e[1]).title)}</h3><p>${esc(e[3])}</p>${sourceLink(e[4])}</section>`).join('')}`:''}</div></details>`;
}
function openStory(id){const s=narratives.find(s=>s.id===id);if(!s)return;const i=narratives.indexOf(s),next=narratives[(i+1)%narratives.length];
$('#reader-content').innerHTML=`<div class="reader-heading"><p class="eyebrow">${esc(s.category)} · ${esc(s.period)} · ${readingMinutes(s)} MIN READ</p><h1 id="reader-title">${esc(s.title)}</h1><p class="reader-dek">${esc(s.dek)}</p></div>${storyPortraits(s)}<div class="reader-body">${s.chapters.map(([h,p],i)=>`<section class="chapter"><span class="chapter-number">0${i+1}</span><h2>${esc(h)}</h2><p>${esc(p)}</p>${storyVisuals[s.id]?.chapters[i]?mediaFigure(storyVisuals[s.id].chapters[i],'chapter-image'):''}</section>`).join('')}${storyDeepDive(s)}<div class="history-note"><strong>A note on the history</strong><p>${esc(s.note)}</p></div><div class="reader-links"><h3>Meet the people</h3>${s.people.map(id=>`<button data-open-person="${esc(id)}">${esc(pMap.get(id).title)}</button>`).join('')}<h3>Follow the discoveries</h3>${s.discoveries.map(id=>`<button data-open-discovery="${esc(id)}">${esc(dMap.get(id).title)} · ${esc(date(dMap.get(id)))}</button>`).join('')}</div><details class="reading-sources"><summary>Sources & further reading</summary>${s.sources.map(sourceLink).join('')}<p>Original narrative based on the sources above. No invented dialogue.</p></details><button class="next-story" data-narrative="${next.id}"><small>READ ANOTHER STORY</small>${esc(next.title)}</button></div>`;
const dialog=$('#story-reader');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.body.classList.add('reader-open');$('#close-reader').focus();
$('#reader-content').querySelectorAll('[data-open-person]').forEach(b=>b.onclick=()=>openNode(b.dataset.openPerson,'people'));$('#reader-content').querySelectorAll('[data-open-discovery]').forEach(b=>b.onclick=()=>openNode(b.dataset.openDiscovery,'discoveries'));bindStoryButtons($('#reader-content'));history.replaceState(null,'',`#story=${s.id}`);
}
function closeReader(restore=true){const d=$('#story-reader');if(d.open)d.close();document.body.classList.remove('reader-open');if(restore){history.replaceState(null,'','#stories');if(lastReaderTrigger?.isConnected)lastReaderTrigger.focus()}}
$('#close-reader').onclick=()=>closeReader();$('#story-reader').addEventListener('cancel',e=>{e.preventDefault();closeReader()});$('#story-reader').addEventListener('click',e=>{if(e.target===$('#story-reader'))closeReader()});
$('#story-filters').innerHTML=['All stories',...new Set(narratives.map(s=>s.category))].map(c=>`<button data-story-category="${esc(c)}" aria-pressed="${c===storyCategory}">${esc(c)}</button>`).join('');$$('[data-story-category]').forEach(b=>b.onclick=()=>{storyCategory=b.dataset.storyCategory;storyLimit=6;renderStories()});$('#story-search').oninput=()=>{storyLimit=6;renderStories()};$('#more-stories').onclick=()=>{storyLimit+=6;renderStories()};
$('#field').innerHTML='<option value="All">All subjects</option>'+[...new Set(discoveries.map(d=>d.field))].sort().map(f=>`<option>${esc(f)}</option>`).join('');
$$('[data-mode]').forEach(b=>b.onclick=()=>{const nextMode=b.dataset.mode;journey=null;clearFilters();selected=nextMode==='people'?'faraday':mode==='people'?'gravity':selected;mode=nextMode;render()});
$('#search').oninput=()=>{limit=24;journey=null;render()};for(const id of ['field','era','relation'])$('#'+id).onchange=()=>{limit=24;journey=null;render()};
$('#network-depth').onclick=()=>{if(networkView==='all'){networkView='focus';widerNetwork=false}else if(!widerNetwork){widerNetwork=true}else{networkView='all'}zoom=.85;render()};$('#fit-map').onclick=()=>{zoom=.85;constellation?.fit()};
function changeZoom(factor){zoom=Math.min(5.1,Math.max(.425,zoom*factor));constellation?.zoom(factor)}
$('#zoom-in').onclick=()=>changeZoom(1.35);$('#zoom-out').onclick=()=>changeZoom(1/1.35);$('#reset').onclick=()=>{clearFilters();zoom=.85;journey=null;networkView='all';render();constellation?.fit()};$('#load-more').onclick=()=>{limit+=24;render()};
$('#journeys').innerHTML=stories.map((s,i)=>`<button class="journey" data-route="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="tag">${esc(s.tag)}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><span class="open">Follow ${s.ids.length} stops</span></button>`).join('');$$('[data-route]').forEach(b=>b.onclick=()=>{clearFilters();journey=stories[+b.dataset.route];step=0;mode='discoveries';selected=journey.ids[0];render();$('#explore').scrollIntoView({behavior:'smooth'});$('#detail').scrollTop=0});

function readHash(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('story='))openStory(hash.slice(6));else if(hash.startsWith('node=')){const [kind,id]=hash.slice(5).split('/');if((kind==='p'?pMap:dMap).has(id)){clearFilters();mode=kind==='p'?'people':'discoveries';selected=id;render();$('#explore').scrollIntoView()}}}
renderStories();render();readHash();window.addEventListener('hashchange',readHash);


const expandAtlas=document.createElement('button');expandAtlas.id='expand-atlas';expandAtlas.textContent='Expand atlas';$('.map-top>div').append(expandAtlas);
function setAtlasExpanded(expanded){$('.atlas').classList.toggle('is-expanded',expanded);document.body.classList.toggle('atlas-expanded',expanded);expandAtlas.textContent=expanded?'Close expanded view':'Expand atlas';expandAtlas.setAttribute('aria-expanded',expanded);requestAnimationFrame(()=>{constellation?.resize();constellation?.fit();if(expanded)$('#map canvas')?.focus();else expandAtlas.focus()})}
expandAtlas.onclick=()=>setAtlasExpanded(!$('.atlas').classList.contains('is-expanded'));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.atlas').classList.contains('is-expanded'))setAtlasExpanded(false)});
const threadBar=document.createElement('div');threadBar.className='atlas-thread-bar';threadBar.innerHTML='<span>START WITH A THREAD</span><button data-thread="faraday">Faraday’s influence</button><button data-thread="raman">Raman’s circle</button><button data-thread="einstein">Einstein’s connections</button><button id="surprise-thread">Surprise me</button>';$('.atlas').before(threadBar);
threadBar.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{clearFilters();networkView='focus';widerNetwork=false;selectNode(b.dataset.thread,'people')});
$('#surprise-thread').onclick=()=>{clearFilters();const candidates=people.filter(n=>narratives.some(s=>s.people.includes(n.id))&&peopleEdges.some(e=>e[0]===n.id||e[1]===n.id));if(!candidates.length)return;networkView='focus';widerNetwork=false;selectNode(candidates[Math.floor(Math.random()*candidates.length)].id,'people')};
